document.addEventListener("DOMContentLoaded",()=>{console.log("Class 9 Notes JS Loaded"),initClass9NotesScrollAnimations()});function initClass9NotesScrollAnimations(){const s=new IntersectionObserver(e=>{e.forEach(n=>{n.isIntersecting&&n.target.classList.add("active")})},{threshold:.1});document.querySelectorAll(".note-section, .accordion-item, .quiz-container, .card, .interactive-box").forEach(e=>{e.classList.add("reveal"),s.observe(e)})}function toggleAccordion(s){const t=s.nextElementSibling;if(!t)return;s.classList.toggle("active");const e=s.querySelector(".fa-chevron-down, .fa-chevron-up");t.classList.contains("open")?(t.classList.remove("open"),e?.classList.remove("fa-chevron-up"),e?.classList.add("fa-chevron-down")):(t.classList.add("open"),e?.classList.remove("fa-chevron-down"),e?.classList.add("fa-chevron-up")),s.setAttribute("aria-expanded",String(t.classList.contains("open")))}function checkQuiz(s,t){const e=s.parentElement;if(e.dataset.quizAnswered==="true")return;e.dataset.quizAnswered="true";const n=e.querySelectorAll(".quiz-option");n.forEach(c=>c.style.pointerEvents="none"),t?(s.classList.add("correct","pop"),s.innerHTML+=' <i class="fas fa-check-circle"></i>'):(s.classList.add("wrong","shake"),s.innerHTML+=' <i class="fas fa-times-circle"></i>',setTimeout(()=>{const c=Array.from(n).find(o=>o.getAttribute("onclick")?.includes("true"));c&&(c.classList.add("correct","pop"),c.innerHTML+=' <i class="fas fa-check-circle"></i>')},500))}
